def comp4(grid,bg):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]==bg or (r,c) in seen: continue
       col=grid[r][c]; q=[(r,c)];seen.add((r,c)); cells=[]
       for y,x in q:
        cells.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         ny,nx=y+dy,x+dx
         if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col:
          seen.add((ny,nx));q.append((ny,nx))
       out.append({'color':col,'cells':frozenset(cells)})
    return out

def detect_l(comps,h,w):
    found=[]
    for i,obj in enumerate(comps):
      cells=obj['cells']; col=obj['color']
      for r,c in cells:
       for ds in [(-1,1),(-1,-1),(1,1),(1,-1)]:
        dr,dc=ds
        rr=list(range(r, -1, -1)) if dr==-1 else list(range(r,h))
        cc=list(range(c, -1, -1)) if dc==-1 else list(range(c,w))
        exp={(r,x) for x in cc}|{(y,c) for y in rr}
        if exp==cells:
          found.append((i,col,r,c,dr,dc,len(cells)))
    return found

def transform_candidate(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    cs=comp4(grid,bg); ls=detect_l(cs,h,w)
    if not ls: return [row[:] for row in grid], {'bg':bg,'ls':ls}
    # choose longest line L
    i,col,r,c,dr,dc,n=max(ls,key=lambda x:x[-1]); refq=[]
    for j,obj in enumerate(cs):
      if j==i: continue
      cells=obj['cells']
      if all((y-r)*dr>0 and (x-c)*dc>0 for y,x in cells): refq.append((j,obj))
    def shape(cells):
      mr=min(y for y,x in cells);mc=min(x for y,x in cells)
      return frozenset((y-mr,x-mc) for y,x in cells)
    targets=[]
    for j,ref in refq:
      sig=shape(ref['cells'])
      for k,obj in enumerate(cs):
       if k==i or k==j or shape(obj['cells'])!=sig: continue
       # outside interior quadrant and non-L
       if not all((y-r)*dr>0 and (x-c)*dc>0 for y,x in obj['cells']): targets.append((k,obj,j,ref))
    out=[row[:] for row in grid]
    for k,obj,j,ref in targets:
      for y,x in obj['cells']:out[y][x]=col
    return out, {'bg':bg,'ls':ls,'sel':(i,col,r,c,dr,dc,n), 'refq':[(j,o['color'],len(o['cells'])) for j,o in refq], 'targets':[(k,o['color'],len(o['cells']),j,ref['color']) for k,o,j,ref in targets]}

