program='''from collections import Counter


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            cells = {(r, c)}
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        cells.add((ny, nx))
                        stack.append((ny, nx))
            result.append((color, cells))
    return result


def _shape(cells):
    top = min(r for r, c in cells)
    left = min(c for r, c in cells)
    return frozenset((r - top, c - left) for r, c in cells)


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    objects = _components(grid, background)

    markers = []
    for index, (color, cells) in enumerate(objects):
        for r, c in cells:
            for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                rows = range(r, -1, -1) if dr < 0 else range(r, h)
                cols = range(c, -1, -1) if dc < 0 else range(c, w)
                l_shape = ({(r, x) for x in cols} |
                           {(y, c) for y in rows})
                if cells == l_shape:
                    markers.append((len(cells), index, color, r, c, dr, dc))
    if not markers:
        return [row[:] for row in grid]

    _, marker_index, marker_color, joint_r, joint_c, dr, dc = max(markers)
    refs = []
    for index, (color, cells) in enumerate(objects):
        if index == marker_index:
            continue
        if all((r - joint_r) * dr > 0 and (c - joint_c) * dc > 0
               for r, c in cells):
            refs.append((index, _shape(cells)))

    targets = set()
    for ref_index, signature in refs:
        for index, (_, cells) in enumerate(objects):
            if index == marker_index or index == ref_index:
                continue
            if _shape(cells) == signature and not all(
                    (r - joint_r) * dr > 0 and (c - joint_c) * dc > 0
                    for r, c in cells):
                targets.add(index)

    output = [row[:] for row in grid]
    for index in targets:
        for r, c in objects[index][1]:
            output[r][c] = marker_color
    return output
